import os
import json
from typing import Any, Dict, List, Optional

from azure.ai.formrecognizer import DocumentAnalysisClient
from azure.core.credentials import AzureKeyCredential


AZURE_FORM_RECOGNIZER_ENDPOINT = os.environ["AZURE_FORM_RECOGNIZER_ENDPOINT"]
AZURE_FORM_RECOGNIZER_KEY = os.environ["AZURE_FORM_RECOGNIZER_KEY"]
AZURE_DOCUMENT_INTELLIGENCE_MODEL = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_MODEL", "prebuilt-layout")


def _span_contains(span_offset: int, span_length: int, target_offset: int, target_length: int) -> bool:
    span_end = span_offset + span_length
    target_end = target_offset + target_length
    return span_offset <= target_offset and span_end >= target_end


def _find_cell_words(cell: Any, words: List[Any], content: str) -> List[str]:
    if not getattr(cell, "spans", None):
        return []

    matched = []
    for word in words:
        if not getattr(word, "span", None):
            continue
        for cell_span in cell.spans:
            if _span_contains(cell_span.offset, cell_span.length, word.span.offset, word.span.length):
                matched.append(content[word.span.offset:word.span.offset + word.span.length])
                break
    return matched


def extract_tables_and_rows_from_document(
    file_path: str,
    model_id: str = AZURE_DOCUMENT_INTELLIGENCE_MODEL,
) -> Dict[str, Any]:
    client = DocumentAnalysisClient(
        endpoint=AZURE_FORM_RECOGNIZER_ENDPOINT,
        credential=AzureKeyCredential(AZURE_FORM_RECOGNIZER_KEY),
    )

    with open(file_path, "rb") as f:
        poller = client.begin_analyze_document(model_id=model_id, document=f)
        result = poller.result()

    content = result.content or ""
    pages_output: List[Dict[str, Any]] = []

    all_words: List[Any] = []
    for page in result.pages or []:
        all_words.extend(page.words or [])

    for table_index, table in enumerate(result.tables or []):
        rows_map: Dict[int, List[Dict[str, Any]]] = {}

        for cell in table.cells or []:
            row_index = int(cell.row_index)
            column_index = int(cell.column_index)
            row_span = int(getattr(cell, "row_span", 1) or 1)
            column_span = int(getattr(cell, "column_span", 1) or 1)

            cell_text = (cell.content or "").strip()
            cell_words = _find_cell_words(cell, all_words, content)

            bbox = None
            if getattr(cell, "bounding_regions", None):
                region = cell.bounding_regions[0]
                if getattr(region, "polygon", None):
                    bbox = [{"x": p.x, "y": p.y} for p in region.polygon]

            cell_data = {
                "text": cell_text,
                "row_index": row_index,
                "column_index": column_index,
                "row_span": row_span,
                "column_span": column_span,
                "kind": getattr(cell, "kind", None),
                "bounding_polygon": bbox,
                "words": cell_words,
            }

            rows_map.setdefault(row_index, []).append(cell_data)

        rows_output: List[Dict[str, Any]] = []
        for row_index in sorted(rows_map.keys()):
            cells_sorted = sorted(rows_map[row_index], key=lambda c: c["column_index"])
            rows_output.append(
                {
                    "row_index": row_index,
                    "cells": cells_sorted,
                    "text": " | ".join(cell["text"] for cell in cells_sorted),
                }
            )

        table_pages = []
        for region in getattr(table, "bounding_regions", []) or []:
            if getattr(region, "page_number", None) is not None:
                table_pages.append(region.page_number)

        pages_output.append(
            {
                "table_index": table_index,
                "row_count": int(table.row_count),
                "column_count": int(table.column_count),
                "page_numbers": sorted(set(table_pages)),
                "rows": rows_output,
            }
        )

    return {
        "provider": "Azure AI Document Intelligence",
        "model_id": model_id,
        "tables": pages_output,
    }


def extract_tables_and_rows_json(file_path: str, model_id: Optional[str] = None) -> str:
    data = extract_tables_and_rows_from_document(
        file_path=file_path,
        model_id=model_id or AZURE_DOCUMENT_INTELLIGENCE_MODEL,
    )
    return json.dumps(data, ensure_ascii=False, indent=2)
